contract Pool {
    mapping(address => uint256) shares;
    IRouter public router;

    function redeem(uint256 shareAmount) external {
        // CEI looks correct at first glance...
        shares[msg.sender] -= shareAmount; // state update first
        uint256 ethAmount = shareAmount * pricePerShare;
        router.execute{value: ethAmount}(msg.sender); // router callbacks Pool.deposit!
    }

    // NOT guarded — attacker exploits via router callback
    function deposit() external payable {
        shares[msg.sender] += msg.value / pricePerShare; // stale pricePerShare
    }
}

mapping(address => uint256) public balances;

function claimAll() external {
    uint256 amount = balances[msg.sender];
    require(amount > 0, "nothing to claim");
    balances[msg.sender] = 0; // CLEARED immediately — re-entry sees 0
    // external call: if attacker re-enters claimAll, require(amount > 0) will revert
    (bool ok, ) = msg.sender.call{value: amount}("");
    require(ok, "transfer failed");
    // redundant check — balance already 0 above
    assert(balances[msg.sender] == 0);
}

bool public isEmergency;
bool private locked;

modifier conditionalGuard() {
    // Guard only applies in normal mode!
    if (!isEmergency) {
        require(!locked, "reentrant");
        locked = true;
        _;
        locked = false;
    } else {
        _; // emergency: no guard!
    }
}

function emergencyWithdraw(uint256 amount) external conditionalGuard {
    balances[msg.sender] -= amount;
    (bool ok,) = msg.sender.call{value: amount}("");
    require(ok);
}

contract AMM {
    uint256 public reserve0; // ETH
    uint256 public reserve1; // Token

    // Called by lending protocol to get collateral price
    function getSpotPrice() external view returns (uint256) {
        return (reserve1 * 1e18) / reserve0; // reads reserves
    }

    function swap(uint256 ethIn) external payable {
        // External callback BEFORE reserve update
        ICallback(msg.sender).onSwapReceive{value: ethIn}();
        // attacker calls getSpotPrice() from onSwapReceive — sees stale reserves!
        reserve0 += ethIn; // state updated AFTER callback
        reserve1 -= ethIn * reserve1 / reserve0;
    }
}
